"""Private paired H02 content. Fixed paper puzzle, never imported by the browser."""
from pathlib import Path
import json
from free_game_zh_content import P,text,box,grid,cards,lines,special
E=json.loads((Path(__file__).resolve().parents[1]/'shared/dinosaur-home-edition.json').read_text(encoding='utf-8'))

def jobs(n,m):
    bundles={2:['R/C','M/S'],3:['R/C','M','S'],4:['R','M','S','C'],5:['R-read','R-point','M','S','C'],6:['R-read','R-point','M-place','M-check','S','C']}[n]
    return [bundles[(i-(m-1))%n] for i in range(n)]

def content(locale):
    z=locale=='zh';T=lambda en,zh:zh if z else en
    def steps(*items):return text('<br/>'.join(f'{i}. {v}' for i,v in enumerate(items,1)))
    keep=box(T('Before the next mission','领取下一关前'),T('Keep the original pieces and record. Show the host the action and evidence, correct any mismatch, then change jobs using the seat table. Later pages stay with the adult.','保留原件与记录，向成人主持人演示操作并指出依据；有差异先修正，再按座位表换任务。后续页仍由成人保管。'))
    p=[
      P(E['titles'][locale],T('Dinosaur Home / H02 / ages 6–12 with adult reading support','恐龙世界／家庭版 H02／6至12岁，可由成人协助朗读'),special('cover'),
        box(T('Milo needs your help','米洛需要你们帮忙'),T('Milo is safe on a paper trail. Find his starting place, rebuild the scattered map, pack two paper supplies and adapt when the weather changes. The welcome at camp stays with your adult until the final check.','米洛安全地等在纸上小路旁。请找到他的起点，拼好散开的地图，装两件纸补给，再应对天气变化。营地的欢迎结局由成人保管，最终核查后才揭晓。')),
        box(T('Start with pages 1–3 only','开始只领第1至3页'),T('One adult hosts 2–6 players per team. For 7–12 players, prepare two complete independent sets. Choose jobs on page 2; keep page 3 whole. All play stays at the table.','每组2至6名玩家，由一名成人主持。7至12人准备两套完整独立材料。按第2页分工，第3页整页保留，活动都在桌面进行。')),
        text(T('Use ordinary paper, pencil/eraser and adult-handled scissors. Point, move pieces, dictate or ask for reading help. No real boots, lamp, river, dinosaur toy or purchased prize is needed.','只需普通纸、铅笔、橡皮和成人操作的剪刀。可以指认、移动纸件、口述或请成人朗读，不需真实雨靴、灯、河流、恐龙玩具或另购奖品。'))),
      P(T('Four explorer jobs','四种探险分工'),T('Full-cut: adult cuts the four role cards. Low-cut: keep this page whole and point to jobs. No puzzle clues are hidden here.','全剪由成人剪四张角色卡；少剪整页保留并指认分工。本页不隐藏谜题线索。'),special('jobs'),
        box(T('Change jobs, include everyone','轮换任务，每人参与'),T('Use the Host Guide seat tables after missions 1–4. A role pair shares one card: one reads or places, the other points or checks; exchange these actions during the mission. Checker/Recorder is one combined family job; the adult independently verifies every result.','第1至4关后按主持指南座位表换任务。双人角色共用一张卡：一人读或摆，一人指或核，一关中交换一次动作。核查记录员是合并的一项家庭任务，成人还会独立核准各关。'))),
      P(T('Our expedition record','本组探险记录'),T('Keep whole. Record each discovery once; point to the retained map and tokens instead of copying them again.','本页不剪，每项发现只记一次；地图与纸件保留，用指认代替反复抄写。'),
        lines([T('1 / Matching track numbers, then the starting word','1／相符脚印编号，再写起点名称'),T('2 / Map checked: all facing exits agree; top marks stay up','2／地图已核：接边出口对应，卡顶标记朝上'),T('3 / Two supplies packed: show the actual tokens','3／两件补给已装好：出示实际纸卡'),T('4 / Actual journey to the tunnel: four places in order','4／实际走到隧道：依次记录四个地点'),T('5 / Evidence checked; Milo moved into camp once','5／证据已核：米洛已核准移入营地')]),
        box(T('Record what really happened','如实记录实际过程'),T('A partner may write your words or tick after you demonstrate. If you changed a choice, explain it; if it worked first time, keep it. You do not need to invent a mistake or copy a long account.','伙伴可照口述代写，演示后再勾选。确实换过选择就说明原因；首次成功就保留。不编造错误经历，也不必写长篇经过。'))),
      P(T('Mission 1 / read the trail marks','第1关／辨认脚印'),T('Only the current mission is open. The six-print sheet stays whole.','只打开当前关，六脚印页整页保留。'),
        box(T('Read the scene','读场景'),T('Rain has washed the paper trail. Milo has three toe marks, a round heel and one notch on the right. Some prints are his; others differ. Their labels will reveal where the journey starts.','雨水冲过纸上小路。米洛的脚印有三个脚趾、圆脚跟，右侧有一个缺口。有些脚印属于他，有些不符合。找对后，标签会告诉你们从哪里出发。')),
        steps(T('Read all three features. On page 5, point to toes, heel and right edge. Right means the printed page kept upright.','读出三个条件，在第5页指出脚趾、脚跟和右侧。右侧以纸页文字正向为准。'),T('Circle every print meeting ALL three conditions; keep rejected prints visible too.','圈出同时符合三项的所有脚印，未选中的也保留可见。'),T('Read the labels of matching prints in increasing number order. Ask the adult to read a label if needed.','按编号从小到大读出相符脚印的标签；不认识的字可请成人朗读。'),T('Record the source numbers and starting word once on page 3. Explain why one other print fails.','在第3页只记一次来源编号和起点名称，并解释一个其他脚印为何不符。')),keep),
      P(T('Six rain-marked prints','六枚雨后脚印'),T('Keep whole. Match toes, heel and the right notch. Read labels only from the matching prints, in number order.','本页不剪。核对脚趾、脚跟和右侧缺口；只按编号顺序读取相符脚印的标签。'),special('tracks')),
      P(T('Mission 2 / rebuild the map','第2关／拼好地图'),T('Use the neutral example on page 7, the whole board on page 8 and all six tiles from page 9.','使用第7页中性示例、第8页整张底板和第9页六张地形卡。'),
        box(T('Read the scene','读场景'),T('Wind scattered the map. The starting place belongs at A1. Camp is beyond the east side of C2. Rebuild a landscape with matching path exits.','风把地图吹散了。起点放在A1格，营地在C2格右侧。请按相邻出口拼好这片地形。')),
        steps(T('Adult cuts the six OUTER tile borders. Keep every card face up, words upright and TOP arrow pointing to the board top. Do not rotate or flip tiles.','成人剪六张地形卡的外框。每卡正面朝上、文字正向，卡顶箭头与底板上方一致；不能旋转或翻面。'),T('Place the starting-place tile at A1. Find the tile whose own clue puts camp to its east, and use the C2 connection.','把起点卡放A1；找出自身线索说明营地在它右侧的地形卡，对照C2外接位置。'),T('Use all six tiles. Across an internal shared edge, two solid exits must face each other, or both edges must have no exit. No path leaves the outer border except the camp connection.','六张卡都要用。每条内部接边要么两边都有相对的实线出口，要么两边都无出口；除营地连接外，道路不出底板外边。'),T('Use the printed alignment marks across cutting gaps. Dashed board guides alone are not roads. Trace every usable join and let the adult check before marking page 3.','按对齐标记核对裁剪留缝两侧的出口，底板虚线本身不算路。逐一指出可通接边，成人核准后在第3页标记。')),keep),
      P(T('How paper path exits connect','纸路怎样才算相连'),T('Neutral examples only. These are not game tiles and do not reveal the completed map. Keep whole.','这里只用中性示例，不是游戏地形卡，也不展示完整地图。本页不剪。'),special('join-demo'),
        box(T('One consistent rule','统一连接规则'),T('Centre each tile in its matching slot, with TOP up. Small blank cutting gaps are intentional. Count a join only when BOTH solid path ends reach the facing marked positions. A dashed guide beside a closed tile cannot create a road. Move only between edge-neighbours, never diagonally.','每张卡居中放入对应格，卡顶朝上，周围留白是裁剪余量。只有两侧实线出口都到达相对标记位置才算相连；闭合卡边旁的虚线不能变出路。只能移到共边的相邻格，不能斜跳。'))),
      P(T('The expedition board','探险地图底板'),T('Keep whole and flat. Six slots plus a separate camp finish. Grey dashed gap guides show alignment, not an answer or an extra road.','整页平放不剪。六个格子，另有独立营地终点；灰色虚线留缝标记只供对齐，不是答案或额外道路。'),special('board')),
      P(T('Six shuffled landscape tiles','六张乱序地形卡'),T('Adult cuts SIX outer dashed borders. Retain each name, TOP mark, clue and solid path endpoint. Do not rotate or flip during play.','成人剪六张外框虚线卡，保留名称、卡顶标记、线索和实线出口。游戏时不旋转、不翻面。'),special('tiles')),
      P(T('Mission 3 / pack two supplies','第3关／装好两格背包'),T('The map remains on the table. Use backpack page 11 and all four cut tokens from page 12.','地图留在桌上，使用第11页背包和第12页全部四件补给纸卡。'),
        box(T('Read the weather report','读天气报告'),T('Clouds gather above the bridge. It may close completely. The other crossing has wet stones, and the passage before camp is dark. Milo can pack only two supplies.','木桥上方乌云聚集，木桥可能完全封闭。另一处过水地有湿石，营地前的通道很暗。米洛只能装两件补给。')),
        steps(T('Inspect all four printed supply effects before choosing. Supplies are paper story tools.','选择前看完四张卡的作用；补给都是纸上故事工具。'),T('Trace both branches of your assembled map. Which branch would remain if the bridge closed?','在拼好的地图上指过两条分支；木桥封闭后哪条还能走？'),T('Place exactly two chosen tokens in the two backpack slots; keep the other two outside and visible.','把选好的两件放入背包两格，另两件留在外面可见。'),T('Explain which obstacle each chosen tool helps with. Show the host your choices and point to the map; no duplicate copying is needed.','解释每件如何帮助应对障碍，向成人出示选择并指地图，不必重复抄写。')),keep),
      P(T('Two-slot backpack / keep whole','两格背包／整页保留'),T('Put exactly two chosen supply cards in these slots. Do not cut the backpack. Keep unused choices beside it.','两格各放一件选中的补给，不剪背包；未选纸卡放在旁边。'),special('backpack'),
        box(T('If a choice needs changing','需要换选择时'),T('Stop and compare your map and the printed supply effects. The adult may give one hint. Repack from all four choices, return any parked used cards first, then repeat the journey from the starting tile. Keep only the supplies actually chosen this attempt.','停下，对照地图和补给卡作用；成人可给一条提示。先收回已停放的使用卡，再从全部四件中重新选两件，从起点重走。背包只保留本次实际选择。'))),
      P(T('Four supply tokens','四件补给纸卡'),T('Adult cuts FOUR outer dashed borders. Deal all four without preselecting. Keep names and printed effects on every token.','成人剪四张外框虚线卡，四件全部发出，不预先选好；保留名称和作用说明。'),special('supplies')),
      P(T('Mission 4 / change the route','第4关／暴雨后换条路'),T('Only now receive the storm mat on page 14 and the two markers from page 15.','现在才领第14页暴雨底板和第15页两个标记。'),
        box(T('Read the scene','读场景'),T('Thunder reaches the fork. The bridge is now closed. Keep the map you built, but test another route. This mission ends at the tunnel; camp arrival is the next mission.','雷声传到岔路，木桥现在封闭。地图不换，请检验另一条路。本关走到隧道就停，下一关才进入营地。')),
        steps(T('Place BLOCK on the closed tile named in the storm notice; place MILO at the starting tile. Do not rearrange or rotate terrain.','按暴雨通知把封路标记放到指定地形，米洛放起点。不得重新排地形或旋转卡片。'),T('Move one edge-connected tile at a time, following both solid exits. No closed tile, diagonal jump or dashed-guide-only crossing is allowed.','每次只移到出口相对的共边邻格，不进封闭地形、不斜跳，也不把只有虚线的留缝当路。'),T('Before entering a wet or dark tile, show the matching PACKED tool. After entering, put that tool in a used-card slot on page 14 and record the tile name. Keep roads visible.','进入湿石或黑暗地形前，出示背包里的对应工具；进入后，把工具放第14页使用卡格并记地形名称，保持道路可见。'),T('If a tool is missing, stop and follow the repack rule on page 11. Stop MILO at the tunnel after both checks. Record the actual four-place journey once on page 3; leave camp empty.','缺工具就停下，按第11页规则重新装包。两次工具核查后，米洛停在隧道；在第3页只记一次实际四地点路线，营地仍留空。')),keep),
      P(T('Storm notice and used tools','暴雨通知与已用工具'),T('Keep whole. Receive only after the two-tool plan is checked. Used tokens park here, not over the map paths.','本页不剪，两件补给计划核准后才发。已用工具放在这里，不压住地图道路。'),special('storm'),
        box(T('Stop before entering camp','进营地前停下'),T('Retain the closed-place marker, actual used tools and map. MILO stays at the tunnel until the mission-5 evidence check. A predicted route is not a completed journey.','保留封路标记、实际用过的工具与地图。第5关证据核查前，米洛留在隧道；预计路线不算已经走完。'))),
      P(T('Two movement markers','两个移动标记'),T('Adult cuts TWO outer dashed pieces and gives them with mission 4. Never cut pieces out of the storm/used-tool mat.','成人剪两个外框虚线件，与第4关一起发出；不能从暴雨和使用工具底板中挖剪纸件。'),special('markers')),
      P(T('Mission 5 / verify, then arrive','第5关／核查后走进营地'),T('MILO begins at the tunnel. Camp is still empty. Final arrival happens once, after the adult checks the evidence.','米洛从隧道开始，营地仍为空。成人核准证据后，才进行唯一一次最终入营地动作。'),
        grid([T('Show the original','出示原件'),T('What the host verifies','成人核对什么')],[[T('Print sheet and record','脚印页与记录'),T('Point to the matching features and starting word.','指出相符特征和起点名称。')],[T('Assembled map and BLOCK','拼好的地图与封路标记'),T('Show facing exits, closed place and actual detour.','指出相对出口、封闭地点和实际绕路。')],[T('Two used tools on page 14','第14页两件已用工具'),T('Point to the obstacle each actually helped with.','指出每件实际帮助通过的障碍。')],[T('Every player contributes','每位玩家有贡献'),T('Place, point, explain or dictate one action.','摆放、指认、解释或口述一次操作。')]],ratios=[.37,.63],row_height=50),
        steps(T('Ask the adult to check. If anything differs, return to its source, correct and repeat that action.','请成人核查；有差异就回到相应原件修正，再重做相应操作。'),T('After acceptance, move MILO once from TUNNEL through the east connection into CAMP. Mark page 3. The adult reads the private welcome and gives page 17.','核准后，米洛从隧道沿右侧连接移入营地，在第3页标记。成人读私用欢迎结局，再发第17页。'))),
      P(T('My expedition keepsake','我的探险纪念页'),T('Optional, after the ending. Draw, point or dictate; this page is not another pass condition.','结局之后自愿完成。可以画、指认或口述，本页不增加通关条件。'),special('keepsake'),
        lines([T('A moment when our plan changed','我们的计划改变时'),T('One way I helped','我帮上的一个忙')]))
    ]
    assert len(p)==17

    stages=[
      (T('Read the trail marks','辨认脚印'),'4–5',
       T('Rain washed the trail. Compare Milo’s three features and read only the matching labels in number order.','雨水冲过小路。请比较米洛脚印的三项特征，只按编号读出相符标签。'),
       T('Give the whole print sheet. Read three toes/round heel/right notch; right is on the upright printed page. Let players point and reject candidates before recording. Read unfamiliar labels aloud without choosing for them.','发整张脚印页，读三个脚趾、圆脚跟、右侧缺口；右以纸页正向为准。玩家先指认并排除，再记录。不熟悉的字可朗读，但不替他们选择。'),
       T('Tracks 1/S, 3/U and 5/N meet all three conditions, spelling SUN. Reject2 for two toes,4 for pointed heel,6 for no notch. Keep these originals and the source-number record.','1／阳、3／光、5／地同时符合，组成阳光地。2只有两趾，4尖脚跟，6无缺口。保留脚印原件与来源编号记录。'),
       [T('Count toes on every print.','逐个数脚趾。'),T('Check the heel and right notch too.','再核脚跟和右侧缺口。'),T('Use1,3,5 in number order; point to every matching feature.','按编号读1、3、5，逐项指出相符特征。')],T('Give6–9 only after start/source evidence is accepted.','起点与来源依据核准后才发6至9页。')),
      (T('Rebuild the upright map','拼好正向地图'),'6–9',
       T('Keep TOP up. Match facing exits; camp is beyond C2. The blank guides cannot create a road.','卡顶朝上，接边出口相对，营地在C2外侧。底板虚线不能变出路。'),
       T('Use the neutral example on Player page 7, the whole board on page 8 and the six cut tiles from page 9. Centre each tile. Do not rotate/flip. Require both facing ports or neither; forbid all outer exits except C2 east into camp. Check the actual path ends across the alignment gaps, then keep the assembled map.','使用玩家第7页的中性示例、第8页整张底板和第9页剪下的六张地形卡。卡片居中放，不旋转、不翻面。内部接边两边都有出口或都没有，外边仅C2右侧可接营地。核对留缝两侧实际路口，拼好地图保留。'),
       T('Top A1 SUN, B1 FERN, C1 BRIDGE; bottom A2 HOLLOW, B2 FORD, C2 TUNNEL. HOLLOW has no exit. FERN branches via BRIDGE or FORD; both reach TUNNEL, whose east exit reaches CAMP. Upright rules make this arrangement unique.','上排A1阳光地、B1蕨叶地、C1木桥；下排A2林间空地、B2浅滩、C2隧道。空地无出口。蕨叶地经木桥或浅滩都到隧道，隧道右出口接营地；正向规则下拼法唯一。'),
       [T('Find the starting tile and TOP marks.','先找起点卡与卡顶标记。'),T('A1 is start; C2 connects to camp. Check each facing side.','A1是起点，C2接营地，逐条核相对卡边。'),T('Show the top/bottom arrangement from this answer and ask players to demonstrate every connection.','成人按本页上下排说明协助，再请玩家演示每处连接。')],T('After map acceptance, give10–12; keep the map visible.','地图核准后发10至12页，地图保持可见。')),
      (T('Pack for the possible detour','为可能的绕路装包'),'10–12',
       T('The bridge may close. Which two tools cover the other branch and the dark passage?','木桥可能封闭，哪两件工具能帮助走另一分支和黑暗通道？'),
       T('Give all four tokens and the empty mat. Compare printed effects and map before packing exactly two. Players explain both choices; adult hints never preselect the two during setup. A wrong choice may be reconsidered without penalty.','发全部四卡和空背包，先比作用与地图，再装恰好两件。玩家解释两项选择；准备时不替他们先选两件。选错可重新考虑，不扣分。'),
       T('Pack BOOTS for wet FORD and LANTERN for dark TUNNEL. ROPE helps only an OPEN bridge and cannot reopen a closed one. SNACK is for a rest; it removes neither required obstacle. Keep all choices.','装雨靴帮助过湿石浅滩，提灯帮助过黑暗隧道。绳子只帮助通过开放木桥，不能打开封闭木桥；点心供休息，不解决必经的湿石或黑暗障碍。全部选择保留。'),
       [T('Which route survives a full bridge closure?','木桥完全封闭后还剩哪条路？'),T('Read each remaining obstacle and each tool effect.','读剩余障碍及各工具作用。'),T('Choose BOOTS and LANTERN; point to their two printed effects.','选雨靴和提灯，指出两条卡面作用。')],T('After two-tool reasoning is checked, give13–15.','两件补给及理由核准后才发13至15页。')),
      (T('Follow the storm detour, stop at tunnel','沿暴雨绕路，停在隧道'),'13–15',
       T('The bridge is now closed. Test the detour and stop before the final camp move.','木桥现在封闭，请检验绕路，在最后入营地动作前停下。'),
       T('BLOCK covers BRIDGE, MILO starts at SUN. Keep terrain fixed. Check two solid-facing ports for each move. Before entering a wet/dark tile, require a matching packed tool; then park the used tool on mat14 with its tile name. Stop at TUNNEL. If a tool is missing, return used cards, repack from all four, restart from SUN and recheck. Record only the actual completed four-place segment.','封路标记盖木桥，米洛从阳光地开始，地形不动，每步核两个相对实线出口。进入湿石或黑暗地形前核背包工具，进入后停在14页使用格并记地点，米洛停在隧道。缺工具就收回使用卡，从四卡重新选两件，从阳光地重试。只记录实际走完的四地点段。'),
       T('Actual segment: SUN→FERN→FORD→TUNNEL. BOOTS is parked with FORD, LANTERN with TUNNEL. BRIDGE stays blocked; CAMP stays empty. Reject jumps, missing tools and proposed journeys presented as observations.','实际段为阳光地→蕨叶地→浅滩→隧道。雨靴停放并标浅滩，提灯停放并标隧道。木桥保持封闭，营地为空。不接受跳格、缺工具或把预计路线说成实际结果。'),
       [T('What does BLOCK prevent?','封路标记禁止走哪里？'),T('At the fork, test the other facing exit and the tools.','在岔路试另一相对出口，并核工具。'),T('Demonstrate SUN–FERN–FORD–TUNNEL and both tools. Keep CAMP empty.','协助演示阳光地、蕨叶地、浅滩、隧道及两工具，营地留空。')],T('Keep all evidence; give16 while MILO remains at tunnel.','保留全部依据，米洛仍在隧道时发16页。')),
      (T('Verify and arrive once','核查并完成唯一一次入营地'),'16',
       T('The camp welcome waits until the journey has evidence. Show what your team really did.','营地欢迎要等旅程有据可查，请展示本组实际做过的操作。'),
       T('Independently check originals as adult: start/track evidence, fixed upright map, closed bridge, actual detour and two used tools labelled on mat14. Invite each child to act/point/dictate. Correct discrepancies without inventing a failure. Only after acceptance ask for the one TUNNEL→CAMP move and mark progress.','成人独立核对原件：起点脚印、固定正向地图、封闭木桥、实际绕路和14页两件标地点的已用工具。邀请每位孩子操作、指认或口述；有差异修正，不编造失败。核准后才请做唯一一次隧道→营地移动并标进度。'),
       T('Before final move, MILO is at TUNNEL and camp empty. After accepted evidence, it follows the actual east connector and fits inside CAMP. The final card does not require a second written route. Then read Guide17 welcome and give Player17 keepsake.','最终移动前，米洛在隧道，营地为空。证据核准后沿实际右侧连接进入营地，标记完整放入。无需再抄第二份路线。随后读主持17页欢迎，并发玩家17页纪念页。'),
       [T('Which original supports each claim?','每项说法由哪份原件支持？'),T('Show the map, closed place and both used tools before moving.','移动前展示地图、封闭地点和两件已用工具。'),T('Use private answers to locate a mismatch, then repeat that action before the camp move.','成人用私用答案定位差异，重做相应操作后再入营地。')],T('Read the private welcome only after the accepted final move.','最终移动核准后才读私用欢迎结局。'))
    ]
    def seat(n):
        cn={'R':'读','M':'图','S':'补','C':'核记','R-read':'读／朗读','R-point':'读／指认','M-place':'图／摆放','M-check':'图／核边'}
        conv=lambda s:'/'.join(cn.get(a,a) for a in s.split('/')) if z else s
        return grid([T('Seat','座位')]+[T(f'M{i}',f'第{i}关') for i in range(1,6)],[[str(j+1)]+[conv(jobs(n,i)[j]) for i in range(1,6)] for j in range(n)],row_height=29)
    g=[
      P(T('Host Guide / start here','成人主持指南／从这里开始'),T('Private adult pages. Each paper size: Player17 pages / Host18 pages. Keep answers off the children’s table.','成人私用，每种纸型均为玩家17页、主持18页。答案不放孩子桌上。'),
        box(T('What your family does','一家人会做什么'),T('Compare prints, build six terrain tiles, pack two supplies, adapt to a closed bridge, then verify and move into camp once. One adult hosts; four family jobs rotate.','比较脚印，拼六张地形，装两件补给，应对封桥，最后核证据并完成唯一一次入营地。由一名成人主持，四种家庭任务轮换。')),
        box(T('Prepare before players arrive','玩家到场前准备'),T('Read pages2–6 and choose the cutting mode. Print one complete Player Pack per team at Actual size, single-sided. Keep the Host Guide private. Begin with Player1–3 only; later piles stay with you.','先读2至6页，选裁剪方式。每组单面、实际大小打印一套完整玩家包；主持指南保密。开始只发玩家1至3页，后续分堆由成人保管。')),
        text(T('No real expedition, weather exposure or powered equipment is involved. Ordinary paper, pencil/eraser and adult-handled scissors are enough. Children may point or dictate while you read/write.','不涉及真实探险、接触天气或动力设备。普通纸、铅笔橡皮、成人操作的剪刀即可。孩子可指认或口述，由成人协助朗读和记录。'))),
      P(T('Print and cutting inventory','打印与裁剪清单'),T('Single-sided /100% Actual size / one paper size within a set. Do not resize individual parts or use fit-to-page.','单面、100%实际大小，同组用同纸型；不单独缩放道具，不用适合页面。'),
        grid([T('Teams','组数'),T('Player sheets','玩家纸张'),T('With one Host Guide','含一份主持指南')],[[T('One team','1组'),'17','17+18=35'],[T('Two teams /7–12 players','2组／7至12人'),'2×17=34','34+18=52']],ratios=[.29,.27,.44],row_height=42),
        box(T('Full-cut /16 pieces per team','全剪／每组16件'),T('4 role cards on2 +6 terrain tiles on9 +4 supplies on12 +2 markers on15. Cut only their outer dashed borders; retain all labels and path ends. Two teams:32 pieces.','2页四角色卡＋9页六地形卡＋12页四补给＋15页两标记。只剪外框虚线，保留标签与路口。两组32件。')),
        box(T('Low-cut /12 pieces per team','少剪／每组12件'),T('Keep role page2 whole; still cut all6 tiles,4 supplies and2 markers separately. Two teams:24 pieces. All other player pages and this guide remain whole. The guide may be read on screen.','2页角色整页指认，六地形、四补给、两标记仍分别剪出。两组24件。其他玩家页和指南都不剪，成人可屏幕读指南。'))),
      P(T('Stage the mission piles','按关分堆发放'),T('Check each team independently before its next pile. Retain originals; no borrowing clues between teams.','各组独立核准后再领下一堆，保留原件，无需向别组借线索。'),
        grid([T('Stage','阶段'),T('Give Player','发玩家页'),T('Condition','条件')],[[T('Start','开始'),'1–3',T('Jobs and record only','只分工与记录')],['1','4–5',T('Find start/source prints','核起点与来源脚印')],['2','6–9',T('Check every map connection','核全部地图接边')],['3','10–12',T('Two-tool plan explained','核两件补给计划')],['4','13–15',T('Use tools, stop at tunnel','用工具，停隧道')],['5','16',T('Check evidence, then enter camp','核证据后才入营地')],[T('After welcome','欢迎后'),'17',T('Optional keepsake','纪念页自愿完成')]],ratios=[.2,.2,.6],row_height=38),
        text(T('The complete welcome is in this private Guide17, never in the Player Pack. Read only the marked scenes aloud; confirm each accepted result and save the welcome for the ending. Keep printed answers and unopened piles out of view.','完整欢迎在本指南17页，不放玩家包。只朗读标注的当前场景；逐关核准操作结果，完整欢迎留到结局再读。印出的答案和未发材料都不展示。'))),
      P(T('Seats and rotation /2–4 players','座位轮换／2至4人'),T('R Reader /M Mapmaker /S Supply Keeper /C Checker & Recorder. Adult independently verifies. Change assignments after missions1–4.','读＝朗读员，图＝地图员，补＝补给员，核记＝核查记录员；成人另行独立核准。第1至4关后换任务。'),text(T('2 players','2人')),seat(2),text(T('3 players','3人')),seat(3),text(T('4 players','4人')),seat(4)),
      P(T('Seats and rotation /5–6 players','座位轮换／5至6人'),T('A pair shares a role card, not an extra clue. Partners exchange reading/pointing or placing/checking within each mission.','同角色伙伴共用一张角色卡，不增加线索。一关中交换朗读与指认、摆放与核边。'),text(T('5: Reader pair only','5人：只把朗读员分成双人')),seat(5),text(T('6: Reader pair and Mapmaker pair','6人：朗读员和地图员各双人')),seat(6),
        box(T('7–12 players /two independent teams','7至12人／两个独立小组'),T('Use two complete sets and assign2–6 players to each team. Share the adult guide, never the puzzle pieces. Check each group before issuing its next pile. Early finishers can explain/recheck, not open later materials.','准备两套完整材料，每组2至6人。可共用成人指南，不共用谜题纸件。各组核准后再发下一堆；先完成组可解释或复查，不提前拆后续材料。'))),
      P(T('Opening, connection rules and recovery','开场、连接规则与重试'),
        T('Read the opening only. Check answers on separate private reference pages after attempts.','只朗读开场，玩家尝试后再看独立私用核对页。'),
        box(T('Opening /read aloud','开场／可照读'),T('Milo is safe on our paper trail. We will inspect prints, build a landscape, pack two tools and respond when the weather changes. You can point, ask, try again and help one another. I will give one mission at a time.','米洛安全地等在纸上小路旁。我们会看脚印、拼地形、装两件工具，再应对天气变化。可以指认、提问、重试和互相帮助。我会一次发一关。')),
        box(T('Paper connection and reading support','纸路连接与朗读协助'),T('Keep TOP up; cards stay face up and unrotated. Centre tiles in slots. A gap guide is usable only with BOTH solid-facing path ends. No diagonal moves or outer exits except camp. Labels duplicate pictures; do not rely on colour. Read unfamiliar words/characters without selecting answers.','卡顶朝上，正面朝上，不旋转，卡居中。留缝标记只有两边实线路口相对才可通过，不斜走，外边只接营地。文字重复图形信息，不依赖颜色；可读不熟悉的词或字，但不替选答案。')),
        box(T('Help and retry without penalty','协助与无惩罚重试'),T('Give one hint and allow an attempt. If a supply is missing, stop, compare printed effects, return parked tools, repack two from all four and restart the actual journey. Accept first success without forced edits. Pause after an accepted mission with all originals stored.','一次给一条提示并留尝试机会。缺工具就停、对卡面作用、收回已用工具，从全部四件重新选两件，重走实际路线。首次成功无需强改。可在任一核准关后保存全部原件暂停。')))
    ]
    for i,(title,give,scene,action,answer,hints,handover) in enumerate(stages,1):
        g.append(P(T(f'Mission {i} /host actions',f'第{i}关／主持操作'),title,
          box(T('Prepare and give','准备与发放'),T(f'Give Player {give}. Keep later materials private.','发玩家第'+give+'页，后续材料保密。')),
          box(T('Scene /read aloud','场景／可照读'),scene),box(T('Guide the action','引导操作'),action),
          box(T('Before acceptance','核准前'),T('Invite each child to move, point, explain or dictate. Use the private next page to check originals after an attempt; do not read its answer aloud as a scene.','邀请每位孩子移动、指认、解释或口述。尝试后用下一页私用答案核原件，不把答案当场景朗读。'))))
        g.append(P(T(f'Mission {i} /adult reference',f'第{i}关／成人核对'),T('Private answers. Use after players try, keep out of their view.','私用答案，玩家先尝试，成人再看，不展示给玩家。'),box(T('Acceptance','通过标准'),answer),box(T('One hint at a time /3 gives direct help','一次一条提示／第三级明确协助'),'<br/>'.join(f'{j}. {v}' for j,v in enumerate(hints,1))),box(T('Keep and hand over','保留与交接'),handover)))
    g += [
      P(T('Private camp welcome','成人私用营地欢迎'),T('Read only after the final accepted move into camp. Give Player17 afterwards.','最终入营地动作核准后才读，再发玩家17页。'),special('finale'),
        box(T('Welcome /read aloud now','欢迎／现在可照读'),T('Milo, welcome home! Your team read the prints, rebuilt the map and chose tools for the changing weather. When the bridge closed, you found another connected path and checked the tools you used. Every helper has a part in this paper journey. The camp is ready for you!','米洛，欢迎回家！大家辨认脚印、拼好地图，还为变化的天气选了工具。木桥封闭后，你们找到另一条相连的小路，并核对实际用过的工具。每位伙伴都帮上了忙，营地准备好迎接你啦！')),
        text(T('The keepsake is optional: draw, point or dictate a memory. No ranking by handwriting, art or speed, and no extra gift is required.','纪念页自愿完成，可画、指认或口述回忆。不按字迹、美术或速度排名，无需额外礼物。'))),
      P(T('Support, reset and bonus challenge','协助、重置与额外挑战'),T('Bonus play happens only after the complete main ending. The printed main route stays fixed.','额外玩法只在主线完整结局后进行，印出的主线规则不变。'),
        box(T('Support or replace a piece','协助或补件'),T('Low-cut retains the four jobs as a whole sheet;12 moving props still need adult cutting. If cutting is unavailable, point to choices or redraw the printed exits with adult help; this is assisted play, not the same physical assembly. Do not preselect the correct supplies. Replace missing pieces from the labelled source page at the same paper size.','少剪只保留四角色整页，12移动道具仍由成人剪。无法裁剪时可指认选择，或由成人协助照原件画出口；这是协助玩法，不等同于实际拼卡。不能预先选好正确补给。缺件按标注原页用同纸型补印。')),
        box(T('Optional /a different closure','可选／另一处封闭'),T('After the ending, imagine FORD closed instead of BRIDGE, without moving or rotating terrain. Answer: SUN→FERN→BRIDGE→TUNNEL→CAMP. With the original two tools, BOOTS is unused; LANTERN helps in the tunnel. This is a post-ending comparison, not a replacement for the storm mission.','结局后，设想浅滩封闭、木桥开放，地形不动不转。答案：阳光地→蕨叶地→木桥→隧道→营地。原两工具中雨靴未用，提灯仍帮助过隧道。这是结局后比较，不替代主线暴雨关。')),
        box(T('Reset or resume','重置或继续'),T('Count16 loose pieces full-cut or12 low-cut, plus every whole mat and record. Retain both selected and rejected choices. Reprint blank records if wanted; replay has the same solution with new jobs. Resume paused play at the next unchecked action, keeping accepted evidence.','全剪核16件、少剪核12件，再核全部整页底板和记录。已选未选都保留。需要时补印空白记录；重玩答案相同，可换任务。暂停后从下一未核操作继续，保留已核依据。')))
    ]
    assert len(g)==18
    return p,g
